package com.xoveconsulting.tests;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.DynamicTest;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestFactory;

import java.io.IOException;
import java.nio.file.Paths;
import java.util.List;
import java.util.stream.Stream;

import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * The suite checks itself, with every {@code mvn test} whichever group is asked for, in well under a
 * second and without a browser: one entry per rule in SUITE-RULES.md, so the report says which rule a
 * test broke ("SR-07 A story has one check"), and the failure says where, why the rule exists, and
 * what to write instead.
 */
@Tag("smoke")
@Tag("navigation")
@Tag("menus")
@Tag("broken-links")
@Tag("stories")
@Tag("rules")
class SuiteRulesTest {

    @TestFactory
    @DisplayName("The suite's rules (SUITE-RULES.md)")
    Stream<DynamicTest> theSuitesRules() throws IOException {
        List<String> problems = SuiteRules.check(Paths.get(System.getProperty("user.dir")));
        return SuiteRules.RULES.stream().map(rule -> DynamicTest.dynamicTest(rule.id() + " " + rule.name(), () -> {
            String tag = "[" + rule.id() + "] ";
            List<String> broken = problems.stream().filter(p -> p.startsWith(tag)).map(p -> p.substring(tag.length())).toList();
            StringBuilder message = new StringBuilder(rule.id() + " " + rule.name() + ": broken " + broken.size()
                    + (broken.size() == 1 ? " time" : " times") + ".\n");
            for (int i = 0; i < broken.size(); i++) message.append("  ").append(i + 1).append(". ").append(broken.get(i)).append('\n');
            message.append("Why the rule: ").append(rule.why()).append('\n');
            message.append("How to fix it: ").append(rule.fix()).append('\n');
            message.append("More, with examples: SUITE-RULES.md, ").append(rule.id()).append('.');
            assertTrue(broken.isEmpty(), message.toString());
        }));
    }

    @Test
    @DisplayName("Every problem the rules find belongs to a rule")
    void everyProblemHasItsRule() throws IOException {
        List<String> problems = SuiteRules.check(Paths.get(System.getProperty("user.dir")));
        List<String> strays = problems.stream()
                .filter(p -> SuiteRules.RULES.stream().noneMatch(r -> p.startsWith("[" + r.id() + "] ")))
                .toList();
        assertTrue(strays.isEmpty(), "Problems no rule claims (a fault in SuiteRules itself: regenerate the suite): " + strays);
    }
}
